local function _bx(a,b)
    local r,p=0,1
    while a>0 or b>0 do
        local x,y=a%2,b%2
        if x~=y then r=r+p end
        a,b,p=math.floor(a/2),math.floor(b/2),p*2
    end
    return r
end
local function _B(s)
